const body = $input.first().json.body;
let eventType = 'unknown';
let commentText = '';
let commentId = '';
let senderId = '';
let accountId = '';
try {
  const entry = body.entry?.[0];
  accountId = entry?.id || '';
  const change = entry?.changes?.[0];
  const messaging = entry?.messaging?.[0];
  if (change?.field === 'comments') {
    eventType = 'comment';
    commentText = change.value?.text || '';
    commentId = change.value?.id || '';
    senderId = change.value?.from?.id || '';
    if (senderId === accountId) eventType = 'own_comment';
  } else if (messaging?.postback) {
    eventType = 'postback';
    senderId = messaging.sender?.id || '';
  } else if (messaging?.message && !messaging.message.is_echo) {
    eventType = 'message';
    commentText = messaging.message.text || '';
    senderId = messaging.sender?.id || '';
  }
} catch (e) {}
return [{ json: { eventType, commentText: commentText.toLowerCase().trim(), commentTextRaw: commentText, commentId, senderId, accountId } }];

const eventData = $('Parse Event').first().json;
const flows = $input.all().map(i => i.json);
let matchedFlow = null;
for (const flow of flows) {
  const kw = String(flow.keyword || '').toLowerCase().trim();
  const text = eventData.commentText || '';
  if (flow.match_type === 'exact' ? text === kw : text.includes(kw)) {
    matchedFlow = flow;
    break;
  }
}
if (!matchedFlow || eventData.eventType !== 'comment') return [{ json: { matched: false } }];
return [{ json: { matched: true, flow: matchedFlow, senderId: eventData.senderId, commentId: eventData.commentId, accountId: eventData.accountId, replyText: matchedFlow.reply_text, dmText: matchedFlow.dm_text, outputValue: matchedFlow.output_value, followerOnly: matchedFlow.follower_only } }];
